//! 🧷️ Concrete empty operation registration retains actual definition/catalog aliases and its native inference owner.
use super::*;
use semio_framework_job::*;
use semio_framework_plugin_decl_tool_contract::{ArtifactInstanceOperationOwnerHandle,ArtifactInstanceOperationOwnerAliasRetirement};
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn fixed<T>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<T>(),depth:1,..Default::default()}}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
/// 🏷️ The exact original registrations and original inference owner enter ToolOperations together.
pub struct OriginalDeclaredOperationTools{binding:OriginalSourceBinding,registry:ManuallyDrop<Option<AppActionRegistry>>,catalog:ManuallyDrop<Option<DeclaredToolCatalogAlias>>,bus:ManuallyDrop<Option<semio_framework::RegisteredActionBusAlias>>,owner:ManuallyDrop<Option<ArtifactInstanceOperationOwnerHandle>>,owner_close:Option<ArtifactInstanceOperationOwnerAliasRetirement>,closing:bool}
impl OriginalDeclaredOperationTools{
 fn empty(binding:OriginalSourceBinding)->Self{Self{binding,registry:ManuallyDrop::new(None),catalog:ManuallyDrop::new(None),bus:ManuallyDrop::new(None),owner:ManuallyDrop::new(None),owner_close:None,closing:false}}
 pub fn bus(&self)->&semio_framework::RegisteredActionBusAlias{self.bus.as_ref().expect("ready original factory bus alias")}
 pub fn registry(&self)->&AppActionRegistry{self.registry.as_ref().expect("ready original registration registry")}
 pub fn into_parts(mut self)->(AppActionRegistry,DeclaredToolCatalogAlias,semio_framework::RegisteredActionBusAlias,ArtifactInstanceOperationOwnerHandle){let parts=(self.registry.take().unwrap(),self.catalog.take().unwrap(),self.bus.take().unwrap(),self.owner.take().unwrap());self.closing=true;parts}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx){return Err(invalid("original registration closure changed its initiating caller").into())}self.closing=true;if let Some(owner)=self.owner.as_ref(){if !owner.close_terminal_is_empty().map_err(OriginalTurnFailure::from)?{let before=cx.retained_progress();let g=cx.retained_grant();let step=owner.close_step(cx,g).map_err(OriginalTurnFailure::from)?;let p=semio_framework_plugin_ownership::bounded_ownership::original_lifecycle_unposted(step.progress().unwrap_or_default(),before,cx.retained_progress())?;cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64);return Ok(false)}let d=fixed::<(Option<ArtifactInstanceOperationOwnerHandle>,Option<ArtifactInstanceOperationOwnerAliasRetirement>)>();close_original_retained_step(cx,d,|_|{self.owner_close=Some(ArtifactInstanceOperationOwnerAliasRetirement::new(self.owner.take().unwrap()));Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(false)}if let Some(owner)=self.owner_close.as_mut(){if owner.terminal_is_empty(){let d=fixed::<Option<ArtifactInstanceOperationOwnerAliasRetirement>>();close_original_retained_step(cx,d,|_|{self.owner_close=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}else{let d=owner.alias_return_demands(4096)?;close_original_retained_step(cx,d,|g|owner.alias_return_step(g))?;}return Ok(false)}if let Some(bus)=self.bus.as_mut(){if bus.terminal_is_empty(){let d=fixed::<Option<semio_framework::RegisteredActionBusAlias>>();close_original_retained_step(cx,d,|_|{self.bus.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}else{let d=bus.close_demands();close_original_retained_step(cx,d,|g|Ok(bus.close_step(g)))?;}return Ok(false)}if let Some(registry)=self.registry.as_mut(){if registry.terminal_is_empty(){let d=fixed::<Option<AppActionRegistry>>();close_original_retained_step(cx,d,|_|{self.registry.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}else{let d=registry.retirement_demands();close_original_retained_turn(cx,d,|g|registry.close_step(g).map_err(OriginalTurnPrimary::Fault))?;}return Ok(false)}if let Some(catalog)=self.catalog.as_mut(){if catalog.terminal_is_empty(){let d=fixed::<Option<DeclaredToolCatalogAlias>>();close_original_retained_step(cx,d,|_|{self.catalog.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}else{let d=catalog.close_demands(4096)?;close_original_retained_step(cx,d,|g|catalog.close_step(g))?;}return Ok(false)}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.registry.is_none()&&self.catalog.is_none()&&self.owner.is_none()&&self.owner_close.is_none()&&self.bus.is_none()}
}
impl Drop for OriginalDeclaredOperationTools{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native registration keeps every actual operation owner and metadata alias until paid closure")}}
/// 🎟️ Energy surfaces explicitly select this empty instance-owner source while real session values use its retained inference registry.
pub struct OriginalDeclaredEmptyOperationSource{binding:OriginalSourceBinding,identity:Option<((usize,usize),(usize,usize))>,owned:ManuallyDrop<Option<OriginalDeclaredOperationTools>>,phase:u8,closing:bool}
impl OriginalDeclaredEmptyOperationSource{
 pub fn birth_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed::<Self>()}}
 pub fn admit(cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if output.is_some(){return Err(invalid("native registration source recipient is occupied").into())}let d=Self::birth_demands();let binding=OriginalSourceBinding::borrow(cx);admit_original_construction(cx,output,construction(d),|_|Ok((Box::new(Self{binding,identity:None,owned:ManuallyDrop::new(Some(OriginalDeclaredOperationTools::empty(binding))),phase:0,closing:false}),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})))?;Ok(output.is_some())}
 pub fn progress(&self)->u8{self.phase}
 pub fn ready(&self)->bool{self.phase==5&&!self.closing}
 pub fn advance(&mut self,definition:RegisteredDefinitionSource<'_>,catalog:DeclaredToolCatalogSource<'_>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx)||self.closing{return Err(invalid("native registration source changed caller or lifecycle").into())}let identity=((definition.id.as_ptr()as usize,definition.id.len()),(catalog.controller_id.as_ptr()as usize,catalog.controller_id.len()));if self.identity.is_some_and(|original|original!=identity){return Err(invalid("native registration source changed its original declarations").into())}if definition.id!=catalog.controller_id{return Err(invalid("native registration catalog does not belong to its original controller").into())}if cx.is_cancelled()||cx.should_yield(){return Ok(false)}let owned=self.owned.as_mut().unwrap();match self.phase{
 0=>{let mut d=AppActionRegistry::original_birth_demands();d.copy_bytes+=size_of_val(&self.identity);let g=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{let(registry,mut p)=AppActionRegistry::admit_original(definition,g)?.ok_or_else(||invalid("native definition alias did not admit its quoted recipient"))?;*owned.registry=Some(registry);self.identity=Some(identity);self.phase=1;p.copied_bytes=d.copy_bytes;Ok(((),p))})?;},
 1=>{let registry=owned.registry.as_mut().unwrap();if registry.original_index_ready(){let d=fixed::<u8>();let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{self.phase=2;Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}else{let d=registry.original_index_demands()?;let g=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|Ok(((),registry.advance_original_index(g)?.progress())))?;}},
 2=>{let d=DeclaredToolCatalogAlias::birth_demands();let g=cx.retained_grant();admit_original_construction(cx,&mut owned.catalog,construction(d),|_|DeclaredToolCatalogAlias::admit(catalog,g)?.ok_or_else(||invalid("native tool metadata alias did not admit its quoted recipient")))?;if owned.catalog.is_some(){self.phase=3;}},
 3=>{let d=catalog.bus.alias_demands();let g=cx.retained_grant();admit_original_construction(cx,&mut owned.bus,construction(d),|_|catalog.bus.admit_alias(g)?.ok_or_else(||invalid("original registered factory bus alias was not funded")))?;if owned.bus.is_some(){self.phase=4;}},
 4=>{ArtifactInstanceOperationOwnerHandle::admit_original_empty(cx,&mut owned.owner)?;if owned.owner.is_some(){self.phase=5;}},_=>{}}
 Ok(self.ready())}
 pub fn take(&mut self,cx:&mut StepContext<'_>,output:&mut Option<OriginalDeclaredOperationTools>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx)||!self.ready()||output.is_some(){return Err(invalid("native registration handoff requires its unchanged ready source").into())}let d=fixed::<OriginalDeclaredOperationTools>();admit_original_construction(cx,output,construction(d),|_|{self.closing=true;Ok((self.owned.take().unwrap(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(output.is_some())}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx){return Err(invalid("native registration cleanup changed its original caller").into())}self.closing=true;if let Some(owned)=self.owned.as_mut(){if !owned.close_step(cx)?{return Ok(false)}let d=fixed::<Option<OriginalDeclaredOperationTools>>();close_original_retained_step(cx,d,|_|{self.owned.take();self.identity=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(false)}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.owned.is_none()}
 pub fn boxed_release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),..fixed::<Option<Box<Self>>>()}}
}
impl Drop for OriginalDeclaredEmptyOperationSource{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native registration source preserves original aliases and inference issuer through cancellation")}}

